/* User supplied photographic backgrounds. */
(function(){var urls={"studio": "data:image/jpeg;base64,", "warm": "data:image/jpeg;base64,", "dark": "data:image/jpeg;base64,", "wheel": "assets/workshop-shelf-wall.webp"},images={};Object.keys(urls).forEach(function(k){var im=images[k]=new Image();im.src=urls[k];});window.TodakBackgrounds={url:function(mode){return urls[mode]||'';},ready:function(mode){var im=images[mode];return !!(im&&im.complete&&im.naturalWidth);},draw:function(c,w,h,mode,view){var im=images[mode];if(!im||!im.complete||!im.naturalWidth)return false;view=view||{};var zoom=Math.max(1,view.zoom||1),s=Math.max(w/im.width,h/im.height)*zoom,dw=im.width*s,dh=im.height*s,x=Math.max(-(dw-w)/2,Math.min((dw-w)/2,(view.panX||0)*w)),y=Math.max(-(dh-h)/2,Math.min((dh-h)/2,(view.panY||0)*h));c.drawImage(im,(w-dw)/2+x,(h-dh)/2+y,dw,dh);return true;}};})();